    desc: {
      ar: `تقع مدينة الأقصر على بعد 670 كم جنوب القاهرة، وكانت مدينة من أربع مدن في إقليم واست الإقليم الرابع قديماً، سُميت قديماً "تا ابت" بمعنى أرض الحرم، ثم أصبحت في اليونانية "تيباي" وحُورت إلى "طيبة"، وفي العصر الروماني تحول المعبد إلى قلعة عسكرية لفرقة اسمها الكسترا ومنها جاءت "الأقصر". كما تبعد مدينة الأقصر 3 كم جنوب مدينة الكرنك، وارتبطت المدينة بنظرية نشأة الخلق التي صاغها كهنة آمون بأن هذه المدينة هي الربوة الأزلية أو التل الأزلي (بن بن) الذي جاء عليه الإله آمون رع كا موت أف الذي خلق نفسه بنفسه ومنه خلقت جميع المخلوقات.\n\nقام باكتشافه وإزالة الردم عنه أوغست مارييت سنة 1870م، فقد كان المعبد مغطى بالرمال حتى أكتاف تماثيل رمسيس الثاني، وكانت أهالي الأقصر يسكنون في وسط المعبد بجوار مسجد أبو الحجاج الأقصري، فقام مارييت بشراء بيوت الأهالي وإزالة الردم ليكشف لنا عن المعبد. وقد وُجدت حفائر من موائد القرابين تحمل اسم سنوسرت الثالث (الأسرة 12) وكذلك سبك حتب (الأسرة 13) مما يدل على قدمية الأبنية المقدسة في هذا المكان. كما قامت الملكة حتشبسوت وتحتمس الثالث بعمل مقاصير بالمعبد حتى جاء الملك أمنحتب الثالث وشيد المعبد الحالي، وقد قام بذلك مهندسه العبقري أمنحتب بن حابو، عدا الأجزاء التوسعية التي قام بها رمسيس الثاني في المدخل الشمالي للمعبد.\n\nاسم المعبد: "إمن بر إم إيبت ريسيت" (IMN PR M IPT RSYT) بمعنى بيت آمون في الحرم الجنوبي، ويظهر الاسم جلياً في مسلة رمسيس الثاني.`,
      zh: `卢克索市位于开罗以南670公里处，古时是上埃及第四诺姆的四座城市之一，古称"塔阿贝特"（意为圣地），希腊语称"底比斯"，罗马时期神庙被改建为名为"卡斯特拉"的军事堡垒，"卢克索"之名即由此而来。卢克索市位于卡纳克神庙以南3公里处，与阿蒙神祭司创造的创世理论相关——该城被认为是永恒的原始丘（本本石），阿蒙-拉神卡穆特夫在此自我创造并创造了万物。\n\n奥古斯特·马里埃特于1870年发掘并清除了覆盖神庙的沙土，当时神庙被沙掩至拉美西斯二世雕像的肩部，当地居民居住在神庙内部阿布哈加格清真寺旁。马里埃特购买了居民房屋并清除沙土，揭示了神庙全貌。考古发现了刻有森乌塞尔特三世（第12王朝）和塞贝克霍特普（第13王朝）名字的祭品桌，证明了此圣地建筑的古老渊源。哈特谢普苏特女王和图特摩斯三世在神庙中建造了神龛，直到阿蒙霍特普三世建造了现存神庙主体，由其天才建筑师阿蒙霍特普·本·哈布负责设计，拉美西斯二世则在神庙北入口进行了扩建。\n\n神庙古名："伊蒙佩雷姆伊佩特雷西特"（IMN PR M IPT RSYT），意为"南圣域中的阿蒙之家"，此名清晰出现在拉美西斯二世的方尖碑上。`
    },
    quote: {
      ar: 'معبد الأقصر ليس مجرد بناء حجري، بل هو سجل حي لتاريخ مصر المتتابع عبر آلاف السنين، من الفراعنة إلى الرومان ثم إلى المسلمين والمسيحيين.',
      zh: '卢克索神庙不仅是石头建筑，更是数千年埃及延续历史的活记录，从法老到罗马人，再到穆斯林和基督徒。'
    },
    quoteSrc: {
      ar: '— الأهمية التاريخية لمعبد الأقصر',
      zh: '— 卢克索神庙的历史意义'
    },
