        { icon: '🌹', title: 'معبد نفرتاري الصغير', text: 'مخصص للملكة نفرتاري والإلهة حتحور. يُجسّد مكانة الملكة الرفيعة في قلب رمسيس الثاني. يُعدّ من أهم الآثار في الموقع بجانب المعبد الكبير.' },
        { icon: '🏺', title: 'صالات الكنوز (الغرف الجانبية)', text: 'حجرتان جانبيتان يؤدي إليهما الجدار الشمالي للقاعة الكبرى. تحتوي جدرانهما على مناظر للملك مع الآلهة. كانت تُستخدم لحفظ الأشياء الثمينة والمقتنيات الخاصة بالمعبد.' },
        { icon: '🎭', title: 'عرض الصوت والضوء', text: 'يُقام كل ليلة. يحكي قصة المعبد عبر إضاءة درامية مذهلة على واجهة التماثيل العملاقة. من أجمل التجارب السياحية في مصر كله.' }
