    innerPlaces: {
      ar: [
        { icon: '☕', title: 'مقهى الفيشاوي', text: 'تقع قهوة الفيشاوي في زقاق ضيق بمنطقة الحسين، وتُعد من أقدم المقاهي في القاهرة بتراث يمتد لأكثر من 200 عام. تتميز بأجوائها التاريخية، من الأرائك الخشبية والمرايا العتيقة إلى رائحة القهوة وأصوات العود، مما يجعل الزائر يشعر وكأنه عاد إلى زمن آخر.', images: ['images/feshawy_cafe1.jpg', 'images/feshawy_cafe2.jpg'], mapUrl: 'https://maps.app.goo.gl/KqPesykeuikhxXUg8' },
        { icon: '📚', title: 'مقهى نجيب محفوظ', text: 'يقدم مقهى نجيب محفوظ تجربة ثقافية متكاملة، من الديكور والأجواء التقليدية إلى الموسيقى الحية الجميلة وتشكيلة الأطباق الشهية. يرتدي النادلون ملابس تقليدية، مما يضفي أجواءً أصيلة على المكان.', images: ['images/naguib-mahfouz-cafe1.jpg', 'images/naguib-mahfouz-cafe2.jpg'], mapUrl: 'https://maps.app.goo.gl/BoYGbyvTZpTssnwS8' },
        { icon: '🚪', title: 'باب الغوري', text: 'باب الغوري هو أحد المداخل التاريخية البارزة في منطقة خان الخليلي بالقاهرة، ويُعرف أيضًا باسم باب البادستان. يتميز البوابة بتصميمها المعماري الفريد، حيث يتكون من قوس مزخرف بنقوش هندسية دقيقة محفورة في الحجر، وتعلوه زخارف نباتية ومقرنصات، بالإضافة إلى نوافذ مشربيات خشبية.', images: ['images/Bab_elghory1.jpg'], mapUrl: 'https://maps.app.goo.gl/vh19jAd28HAgG1oHA' },
        { icon: '🎵', title: 'كافيه أم كلثوم', text: 'في قلب حي الحسين التاريخي، يقع مقهى أم كلثوم، الذي يُعدّ من أبرز المعالم الثقافية في القاهرة. يتميز المقهى بأجوائه الشرقية الأصيلة، حيث تُزيّن جدرانه صور نادرة للمطربة أم كلثوم.', images: ['images/om-kolthom1.jpg'], mapUrl: 'https://maps.app.goo.gl/NXCwmv1ocKDwyGJX6' },
        { icon: '🕌', title: 'شارع المعز', text: 'يعد شارع المعز في القاهرة أحد أقدم الشوارع الإسلامية في العالم، ويمثل متحفًا مفتوحًا يجمع بين العمارة الفاطمية والمملوكية والعثمانية. يجذب هذا الشارع الزوار بتاريخه العريق ومعالمه الأثرية التي تعكس عمق الحضارة الإسلامية في مصر.', images: ['images/elmo3z1.jpg', 'images/elmo3z2.jpg', 'images/elmo3z3.jpg'], mapUrl: 'https://maps.app.goo.gl/NYYBiHhv5tYfxYvJ8' }
      ],
      zh: [
        { icon: '☕', title: '费沙维咖啡馆', text: '费沙维咖啡馆位于侯赛因区一条狭窄的小巷中，是开罗最古老的咖啡馆之一，拥有200多年的传统。它以其历史氛围而著称——木质长椅、古老的镜子、咖啡的芳香和乌德琴的旋律，让访客仿佛穿越回了另一个时代。', images: ['images/feshawy_cafe1.jpg', 'images/feshawy_cafe2.jpg'], mapUrl: 'https://maps.app.goo.gl/KqPesykeuikhxXUg8' },
        { icon: '📚', title: '纳吉布·马哈福兹咖啡馆', text: '纳吉布·马哈福兹咖啡馆提供完整的文化体验，从传统装饰和氛围到优美的现场音乐和丰富的美食。服务员身着传统服饰，为这里增添了浓郁的正宗氛围。', images: ['images/naguib-mahfouz-cafe1.jpg', 'images/naguib-mahfouz-cafe2.jpg'], mapUrl: 'https://maps.app.goo.gl/BoYGbyvTZpTssnwS8' },
        { icon: '🚪', title: '古里门', text: '古里门是开罗汗哈利利地区最著名的历史入口之一，也被称为巴迪斯坦门。这座大门以其独特的建筑设计而著称，由精美的几何图案石雕拱门、植物装饰、蜂窝状垂饰和木质穆沙拉比耶窗格组成。', images: ['images/Bab_elghory1.jpg'], mapUrl: 'https://maps.app.goo.gl/vh19jAd28HAgG1oHA' },
        { icon: '🎵', title: '乌姆·库勒苏姆咖啡馆', text: '在侯赛因历史街区的中心，坐落着乌姆·库勒苏姆咖啡馆，它是开罗最著名的文化地标之一。咖啡馆以正宗的东方氛围而著称，墙上装饰着这位传奇歌手的珍贵照片。', images: ['images/om-kolthom1.jpg'], mapUrl: 'https://maps.app.goo.gl/NXCwmv1ocKDwyGJX6' },
        { icon: '🕌', title: '穆伊兹街', text: '开罗的穆伊兹街是世界上最古老的伊斯兰街道之一，是一座汇集法蒂玛、马穆鲁克和奥斯曼建筑的露天博物馆。这条街道以其悠久的历史和反映埃及伊斯兰文明深度的考古地标吸引着众多游客。', images: ['images/elmo3z1.jpg', 'images/elmo3z2.jpg', 'images/elmo3z3.jpg'], mapUrl: 'https://maps.app.goo.gl/NYYBiHhv5tYfxYvJ8' }
      ]
    },
