    innerPlaces: {
      ar: [
        { icon: '🌆', title: 'الإطلالة البانورامية', text: 'أحد أبرز ما يميز البرج هو إطلالته البانورامية الخلابة على نهر النيل، حيثُ يستطيع الزائر من قمته مشاهدة مجموعة من أهم معالم القاهرة التاريخية، مثل: قلعة صلاح الدين، وقصر عابدين، والجامع الأزهر، وجسر قصر النيل، والحرم القديم للجامعة الأميركية، بل وحتى الأهرامات في الأفق. تُعد هذه الإطلالة من أجمل المشاهد البانورامية في العالم العربي.', images: ['images/burg-elqahira1.jpg'] },
        { icon: '🌸', title: 'تصميم زهرة اللوتس', text: 'يتميز مدخل البرج بتصميمه الدائري الأنيق، مما يمنح الزوار انطباعًا فنيًا منذ اللحظة الأولى، ويُعد ذلك جزءًا من فلسفة التصميم التي اختارت البساطة في الخطوط واستخدام خامات عالية الجودة. عند النظر إلى البرج من الأسفل، يبدو شكله وكأنه زهرة لوتس فرعونية، وهو ما يعكس ارتباط التصميم بجذور الحضارة المصرية القديمة. زهرة اللوتس كانت رمزًا للحياة والنقاء والبعث عند المصريين القدماء.', images: ['images/burg-elqahira2.jpg'] },
        { icon: '🎨', title: 'لوحة الفسيفساء والمطعم الدوّار', text: 'في الداخل، يحتضن البرج لوحة جدارية رائعة من الفسيفساء تُجسّد معالم شهيرة من مختلف أنحاء العالم، مما يضفي عليه بُعدًا ثقافيًا وفنيًا. وعلى قمته، يوجد مطعم دوّار وكافيتريا يتيحان للزائرين الاستمتاع بمشهد بانورامي كامل للمدينة بزاوية 360 درجة، في تجربة تجمع بين سحر المشهد وهدوء المكان. النادلون يرتدون الزي المصري التقليدي في إشارة لطيفة تحافظ على الهوية الثقافية.', images: ['images/fusaifsaa.jpg'] },
        { icon: '🔭', title: 'التليسكوبات ومنصة المراقبة', text: 'تم تزويد القمة بتليسكوبات مُخصصة لمراقبة المعالم المحيطة بدقة ووضوح، وهي مجانية تتيح للزوار الاستمتاع بمشاهدة معالم القاهرة من ارتفاع شاهق. من التفاصيل اللافتة أيضًا، أن البرج يحتوي على نقطة مُخصصة لمراقبة الهواء، ما يضيف له دورًا بيئيًا وتنظيميًا مهمًا إلى جانب دوره السياحي والترفيهي.', images: ['images/burg-elqahira3.jpg', 'images/burg-elqahira4.jpg'] }
      ],
      zh: [
        { icon: '🌆', title: '全景观景台', text: '塔楼最显著的特色之一是其壮丽的尼罗河全景视野。游客可以从塔顶俯瞰开罗众多重要历史地标，包括萨拉丁城堡、阿布丁宫、爱资哈尔清真寺、凯撒尼罗桥、美国大学旧校区，甚至远处的金字塔群。这一全景被认为是阿拉伯世界最美丽的城市景观之一。', images: ['images/burg-elqahira1.jpg'] },
        { icon: '🌸', title: '莲花设计', text: '塔楼入口采用优雅的圆形设计，从第一刻起就给游客留下艺术印象。这是设计理念的一部分——追求简洁线条与高品质材料的运用。从下方仰望塔楼，其形状酷似法老时代的莲花，体现了设计与古埃及文明根源的深厚联系。莲花在古埃及是生命、纯洁和重生的象征。', images: ['images/burg-elqahira2.jpg'] },
        { icon: '🎨', title: '马赛克壁画与旋转餐厅', text: '塔楼内部装饰有精美的马赛克壁画，描绘了世界各地的著名地标，为塔楼增添了文化和艺术维度。塔顶设有旋转餐厅和咖啡厅，让游客可以享受360度全景城市风光，将美食体验与壮丽景色完美结合。服务员身着埃及传统服饰，巧妙地在现代环境中保持了文化认同。', images: ['images/fusaifsaa.jpg'] },
        { icon: '🔭', title: '望远镜与观测平台', text: '塔顶配备了专用望远镜，可以精确清晰地观察周围地标，免费供游客使用，让他们从高空欣赏开罗的壮丽景色。值得注意的是，塔楼还设有专门的空气监测站，除了旅游和娱乐功能外，还承担着重要的环境监测职责。', images: ['images/burg-elqahira3.jpg', 'images/burg-elqahira4.jpg'] }
      ]
    },
