    innerPlaces: {
      ar: [
        { icon: '🪞', title: 'التصميم المزدوج (التناظر)', text: 'المعبد عبارة عن مجمعين متماثلين يتقاسمان نفس المحور، أحدهما مخصص للإله سوبك (إله التمساح) ونصفه الآخر للإله حورس (ذو رأس الصقر). كل نصف يحتوي على مدخل خاص، فناء، صالة أعمدة، وقدس أقداس منفصل. هذا التصميم المتماثل فريد تمامًا ولا يوجد له مثيل في أي معبد مصري آخر، ويعكس فلسفة التوازن بين القوى المتناقضة عند المصريين القدماء.' },
        { icon: '⚕', title: 'النقوش الطبية والجراحية', text: 'تقع على الجدار الخلفي للمعبد، وتُعد من أشهر المناظر في العالم الأثري. تُصور مجموعة من الأدوات الطبية والجراحية المتنوعة: مشارط، مقصات، خطافات، ملاقط، وأدوات كي. هذه النقوش تعكس المستوى المتقدم للطب في مصر القديمة وتُعتبر من أقدم التمثيلات المعروفة للأدوات الطبية في تاريخ البشرية.' },
        { icon: '🐊', title: 'متحف التماسيح', text: 'يقع بجوار المعبد، ويعرض عددًا من مومياوات التماسيح التي تم اكتشافها في المنطقة. كانت التماسيح تُعبد كتمثيل للإله سوبك — إله الخصوبة والقوة. يضم المتحف تماسيح بأحجام مختلفة، بعضها ضخم للغاية، مع توثيق لطقوس التحنيط والعبادة المرتبطة بها.' },
        { icon: '🏛', title: 'قاعات الأعمدة', text: 'توجد قاعتان للأعمدة مزينتان بنقوش بارزة رائعة، تظهر فيها شخصيات الآلهة والملوك البطالمة في مشاهد تقديم القرابين والعبادة. تمت زخرفة هذه القاعات في العصر الروماني بإضافات فنية متميزة، وتتميز الأعمدة بتيجان نباتية مصرية تقليدية (لوتس وبردي) مع تأثيرات يونانية واضحة.' },
        { icon: '🔮', title: 'المزارات وقدس الأقداس', text: 'توجد مزارات داخلية منفصلة لكل من سوبك وحورس، بالإضافة إلى مزارات فرعية للثالوثين المقدسين. النصف الجنوبي يضم ثالوث سوبك (سوبك وحتحور وخونسو)، والنصف الشمالي يضم ثالوث حورس (حورس الأكبر وتاسنتنفرت وبانبتاوي — سيد الأرضين). كل قدس أقداس كان يحوي تمثالًا ذهبيًا للإله.' },
        { icon: '📅', title: 'مناظر التقويم', text: 'نقوش فريدة تُظهر الرموز الهيروغليفية لمواسم الزراعة والفيضان، وروزنامة كاملة للأعياد الدينية والطقوس التي كانت تُقام في المعبد على مدار العام. هذه النقوش تُعد مصدرًا مهمًا لفهم التقويم المصري القديم ودورة الحياة الزراعية المرتبطة بفيضان النيل.' }
      ],
      zh: [
        { icon: '🪞', title: '双重对称设计', text: '神庙由两个完全对称的建筑群组成，共享同一中轴线。一半供奉鳄鱼之神索贝克，另一半供奉隼头之神荷鲁斯。每个半部分都有独立的入口、庭院、柱厅和至圣所。这种对称设计在所有埃及神庙中独一无二，反映了古埃及人对对立力量平衡的哲学信仰。' },
        { icon: '⚕', title: '医疗与外科铭文', text: '位于神庙后墙上，被认为是考古界最著名的场景之一。描绘了各种医疗和外科器械：手术刀、剪刀、钩子、镊子和烙铁。这些浮雕反映了古埃及医学的先进水平，被认为是人类历史上已知最古老的医疗器械图像之一。' },
        { icon: '🐊', title: '鳄鱼博物馆', text: '位于神庙旁边，展示了在该地区发现的多具鳄鱼木乃伊。鳄鱼被视为索贝克神——丰饶和力量之神——的化身而受到崇拜。博物馆收藏了不同大小的鳄鱼，其中一些体型巨大，并记录了与之相关的防腐和崇拜仪式。' },
        { icon: '🏛', title: '柱厅', text: '两座柱厅装饰着精美的浮雕，描绘了神灵和托勒密国王献祭和崇拜的场景。这些大厅在罗马时代又增添了杰出的艺术装饰。柱子顶端有传统的埃及植物柱头（莲花和纸莎草），带有明显的希腊影响。' },
        { icon: '🔮', title: '神殿与至圣所', text: '索贝克和荷鲁斯各有独立的内部神殿，以及两个神圣三位一体的附属神殿。南半部供奉索贝克三位一体（索贝克、哈索尔和孔苏），北半部供奉荷鲁斯三位一体（老荷鲁斯、塔塞奈特奈弗莱特和帕奈布塔维——两地之主）。每个至圣所曾放置一尊金质神像。' },
        { icon: '📅', title: '历法场景', text: '独特的铭文展示了农业和洪水季节的象形文字符号，以及全年在神庙举行的宗教节日和仪式的完整日历。这些铭文是了解古埃及历法和与尼罗河洪水相关的农业生命周期的重要资料。' }
      ]
    },
