        'تُجسد النقوش على جدران الممر الخارجي قصة الصراع بين حورس وعمه ست.',
        'يضم غرفة كانت تُستخدم كمكتبة لحفظ المخطوطات، وأخرى لتجهيز البخور والعطور.'
