        'ما زالت المسلة ملقاة أفقياً ومتصلة بالصخر الجرانيتي الأم حتى اليوم.',
        'تم اختيار موقع المحاجر بالقرب من نهر النيل لتسهيل عملية نقل المسلات والتماثيل الضخمة عبر المياه.',
