        'تمتلك تنوعاً بيولوجياً مذهلاً في الكائنات البحرية كالأسماك الملونة، القرش، التونة، الباراكودا، الدلافين، والسلاحف البحرية.',
        'يوجد بها أكثر من 150 نوعاً من الشعاب المرجانية الصلبة والرخوة.',
