        '“Tiran”岛（61平方公里）和“Sanafir”岛是控制亚喀巴湾具有战略和历史意义的两个岛屿。',
        '“旧市场”区和“贝都因遗产”村以具有竞争力的价格提供卓越的文化和购物体验。',
