        'تضم مساجد تاريخية كمسجد المرسي أبو العباس الأندلسي، والقائد إبراهيم بمئذنته الشاهقة وساعته.',
        'الكاتدرائية المرقسية هي أقدم كنائس مصر، وكانت مقر البطريرك لألف عام.',
        'من متاحفها: المجوهرات الملكية (1919)، اليوناني الروماني (1892)، والقومي (يضم 1800 قطعة).',
