    desc: {
      ar: `تُعد قلعة قايتباي من أهم وأعرق المعالم الأثرية والدفاعية في مدينة الإسكندرية، حيث تقع في نهاية جزيرة فاروس بمنطقة السيالة في حي الجمرك. أمر ببنائها السلطان الأشرف قايتباي سنة 1477م (882 هـ) واستغرق بناؤها عامين. بُنيت القلعة لتكون حصنًا دفاعيًا منيعًا ضد الأخطار القادمة من البحر المتوسط، وتحديداً التهديدات العثمانية في ذلك الوقت.\n\nتتميز القلعة بموقعها الذي يُحيط به البحر من ثلاث جهات، وقد شُيدت فوق أنقاض منارة الإسكندرية القديمة (إحدى عجائب الدنيا السبع) التي تهدمت إثر زلزال 1375م، حيث استُخدمت بعض أحجار المنارة في بناء القلعة. تتكون القلعة من أسوار داخلية تضم الثكنات والمخازن، وأسوار خارجية مزودة بأبراج دفاعية. أما البرج الرئيسي فيقع في الناحية الشمالية الغربية ويتكون من ثلاثة طوابق: الأول يضم مسجد القلعة، والثاني يحوي القاعات، والثالث يتضمن مقعد السلطان وطاحونة وفرناً لخدمة الجنود. عبر العصور، مرت القلعة باهتمام المماليك، ثم استخدمها العثمانيون والفرنسيون ومحمد علي، حتى تم ترميمها في القرن العشرين لتبقى شاهدة على العمارة العسكرية.`,
      zh: `盖特贝城堡被认为是亚历山大最重要和最古老的考古防御地标之一，位于加姆罗克区（El Gomrok）西雅拉（El Sayala）的法罗斯岛（Pharos）尽头。它是由阿什拉夫·盖特贝（Al-Ashraf Qaitbay）苏丹于公元1477年（回历882年）下令建造的，耗时两年建成。该城堡的建造是为了成为抵御来自地中海危险的坚不可摧的防御堡垒，特别是当时奥斯曼帝国的威胁。\n\n这座城堡的特点是三面环海，它建在因1375年地震而摧毁的古亚历山大灯塔（世界七大奇迹之一）的废墟上，城堡的建造使用了灯塔的一些石头。城堡由包含兵营和仓库的内墙，以及配备防御塔的外墙组成。主塔位于西北角，由三层组成：第一层包括城堡清真寺，第二层包含大厅，第三层包含苏丹座位、磨坊和为士兵服务的烤炉。历经几个世纪，这座城堡受到了马穆鲁克人的关注，后来被奥斯曼人、法国人和穆罕默德·阿里使用，直到20世纪进行了修复，至今仍是军事建筑的见证。`
    },
    quote: {
      ar: 'حارس الإسكندرية الأمين.. شيد على أنقاض العجائب ليروي حكايات من العز والصمود.',
      zh: '亚历山大忠实的守卫者……建在奇迹的废墟上，讲述着荣耀与韧性的故事。'
    },
