  { glyph: '𓋴', name: { ar: 'الحضارة الإسلامية', zh: '伊斯兰文明' }, era: { ar: '622 – 1600 م', zh: '622–1600年' }, desc: { ar: 'في عصرها الذهبي، أضاءت الحضارة الإسلامية العالم بعلوم الفلك والطب والرياضيات والعمارة. من بغداد إلى الأندلس، بنى المسلمون مراكز علمية وتحفاً معمارية لا تزال تُبهر.', zh: '在黄金时代，伊斯兰文明以天文学、医学、数学和建筑学照亮了世界。从巴格达到安达卢西亚，穆斯林建造了至今仍令人叹为观止的学术中心和建筑杰作。' }, sites: { ar: ['الحمراء', 'آيا صوفيا', 'قبة الصخرة'], zh: ['阿尔罕布拉宫', '圣索非亚大教堂', '圆顶清真寺'] } },
  { glyph: '𓐍', name: { ar: 'الحضارة الصينية', zh: '中华文明' }, era: { ar: '2100 ق.م — الحاضر', zh: '公元前2100年至今' }, desc: { ar: 'تُعدّ الحضارة الصينية من أقدم وأعرق الحضارات في التاريخ. اخترع الصينيون الورق والطباعة والبارود والبوصلة، وبنوا سور الصين العظيم وأبدعوا في الفنون لآلاف السنين.', zh: '中华文明是世界上最古老、最悠久的文明之一。中国人发明了纸张、印刷术、火药和指南针，建造了万里长城，并在数千年间在艺术方面取得了卓越成就。' }, sites: { ar: ['سور الصين العظيم', 'المدينة المحرمة', 'تيرا كوتا'], zh: ['万里长城', '故宫', '兵马俑'] } },
  { glyph: '𓎼', name: { ar: 'حضارة الإنكا والمايا', zh: '印加与玛雅文明' }, era: { ar: '2000 ق.م — 1500 م', zh: '公元前2000年—1500年' }, desc: { ar: 'في أمريكا قبل الكولومبية، بنت حضارتا الإنكا والمايا إمبراطوريات شاسعة بمعارف فلكية متقدمة ومعمار مبهر. ماتشو بيتشو وتشيتشن إيتزا شواهد على عبقريتهم الفريدة.', zh: '在前哥伦布时代的美洲，印加和玛雅文明建立了广阔的帝国，拥有先进的天文知识和令人叹为观止的建筑。马丘比丘和奇琴伊察是其独特天才的见证。' }, sites: { ar: ['ماتشو بيتشو', 'تشيتشن إيتزا', 'تيكال'], zh: ['马丘比丘', '奇琴伊察', '蒂卡尔'] } }
